package inspect

import (
	_ "embed"
	"fmt"
	"strconv"
	"strings"
	"time"

	"pmm-dump-info/internal/qantype"
)

// qan_columns.txt is generated by tools/update-qan-schema.sh from the
// ClickHouse migrations of PMM (qan-api2/migrations/sql): one block per PMM
// release that changed pmm.metrics, with the columns in "SELECT *" order.
//
//go:embed qan_columns.txt
var qanColumnsFile string

// QANSchemas are the known pmm.metrics layouts, oldest first.
var QANSchemas = mustParseSchemas(qanColumnsFile)

// QANSchemaSet is qan_columns.txt parsed.
type QANSchemaSet struct {
	Source        string // percona/pmm commit the file was generated from
	LatestRelease string // newest PMM release tag when it was generated
	Checked       string // date of the last generation or --check (YYYY-MM-DD)
	Schemas       []*QANSchema
}

// QANSchema is pmm.metrics as of one PMM release.
type QANSchema struct {
	Since      string // first PMM release with this layout, or "unreleased"
	Migrations string // last migration applied
	Cols       []QANColumn
}

// QANColumn is one column with the check its exported values must pass.
type QANColumn struct {
	Name  string
	Type  string
	check func(string) bool
}

func (s *QANSchema) String() string {
	return fmt.Sprintf("since PMM %s (migrations up to %s, %d columns)", s.Since, s.Migrations, len(s.Cols))
}

func (s *QANSchema) index(name string) int {
	for i, c := range s.Cols {
		if c.Name == name {
			return i
		}
	}
	return -1
}

func mustParseSchemas(s string) *QANSchemaSet {
	set, err := ParseQANSchemas(s)
	if err != nil {
		panic("qan_columns.txt: " + err.Error())
	}
	return set
}

// ParseQANSchemas reads the qan_columns.txt format:
//
//	# latest-release: 3.10.0
//	@schema since=3.6.0 migrations=22
//	queryid LowCardinality(String)
//	...
func ParseQANSchemas(s string) (*QANSchemaSet, error) {
	set := &QANSchemaSet{}
	var cur *QANSchema
	for n, l := range strings.Split(s, "\n") {
		l = strings.TrimSpace(l)
		switch {
		case l == "":
		case strings.HasPrefix(l, "#"):
			k, v, ok := strings.Cut(strings.TrimSpace(l[1:]), ":")
			if !ok {
				continue
			}
			v = strings.TrimSpace(v)
			switch k {
			case "source":
				set.Source = v
			case "latest-release":
				set.LatestRelease = v
			case "checked":
				set.Checked = v
			}
		case strings.HasPrefix(l, "@schema "):
			cur = &QANSchema{}
			for _, kv := range strings.Fields(l)[1:] {
				k, v, _ := strings.Cut(kv, "=")
				switch k {
				case "since":
					cur.Since = v
				case "migrations":
					cur.Migrations = v
				}
			}
			set.Schemas = append(set.Schemas, cur)
		default:
			if cur == nil {
				return nil, fmt.Errorf("line %d: column outside a schema block", n+1)
			}
			name, typ, _ := strings.Cut(l, " ")
			typ = strings.TrimSpace(typ)
			check, ok := qantype.Check(typ)
			if !ok {
				return nil, fmt.Errorf("line %d: unsupported ClickHouse type %q", n+1, typ)
			}
			cur.Cols = append(cur.Cols, QANColumn{name, typ, check})
		}
	}
	for _, s := range set.Schemas {
		for _, c := range []string{"queryid", "service_name", "service_type", "period_start"} {
			if s.index(c) < 0 {
				return nil, fmt.Errorf("schema since %s has no %s column", s.Since, c)
			}
		}
	}
	return set, nil
}

// ---- value checks ----

func parseGoTime(s string) (int64, bool) {
	i := strings.LastIndexByte(s, ' ')
	if i < 0 {
		return 0, false
	}
	t, err := time.Parse("2006-01-02 15:04:05 -0700", s[:i])
	if err != nil {
		return 0, false
	}
	return t.UnixMilli(), true
}

// ValidQANType reports whether the tool knows how to check a ClickHouse type.
func ValidQANType(t string) bool {
	_, ok := qantype.Check(t)
	return ok
}

// ---- versions ----

// version turns "3.9.1" (or "v3.9.1-rc1") into a comparable triple.
func version(s string) ([3]int, bool) {
	var v [3]int
	s = strings.TrimPrefix(s, "v")
	parts := strings.SplitN(s, ".", 3)
	if len(parts) < 2 {
		return v, false
	}
	for i, p := range parts {
		j := 0
		for j < len(p) && p[j] >= '0' && p[j] <= '9' {
			j++
		}
		n, err := strconv.Atoi(p[:j])
		if err != nil {
			return v, false
		}
		v[i] = n
	}
	return v, true
}

func versionLess(a, b [3]int) bool {
	for i := range a {
		if a[i] != b[i] {
			return a[i] < b[i]
		}
	}
	return false
}

// newerThanRelease reports whether a PMM version is newer than the latest
// release the schemas were generated against.
func (set *QANSchemaSet) newerThanRelease(pmm string) bool {
	v, ok1 := version(pmm)
	r, ok2 := version(set.LatestRelease)
	return ok1 && ok2 && versionLess(r, v)
}

// forVersion is the layout pmm.metrics has in a PMM version: the newest
// schema whose release is not later. Unreleased schemas only apply to
// versions newer than the latest release.
func (set *QANSchemaSet) forVersion(pmm string) *QANSchema {
	v, ok := version(pmm)
	if !ok {
		return nil
	}
	var best *QANSchema
	for _, s := range set.Schemas {
		if s.Since == "unreleased" {
			if set.newerThanRelease(pmm) {
				best = s
			}
			continue
		}
		if sv, ok := version(s.Since); ok && !versionLess(v, sv) {
			best = s
		}
	}
	return best
}

// withColumns are the schemas with n columns, newest first.
func (set *QANSchemaSet) withColumns(n int) []*QANSchema {
	var out []*QANSchema
	for i := len(set.Schemas) - 1; i >= 0; i-- {
		if s := set.Schemas[i]; len(s.Cols) == n {
			out = append(out, s)
		}
	}
	return out
}

// staleAfter is when a reminder to re-run tools/update-qan-schema.sh shows.
const staleAfter = 30 * 24 * time.Hour

func (set *QANSchemaSet) stale(now time.Time) bool {
	t, err := time.Parse("2006-01-02", set.Checked)
	return err != nil || now.Sub(t) > staleAfter
}
